# -*- coding: utf-8 -*-

from taf.internal.bmc.interfaces.redfish.base import Redfish, RedfishConfiguration
from .system import SystemOe19

from taf.internal.bmc.interfaces.redfish.protocol import redfish_client


class RedfishOe19(Redfish):
    """
    Redfish interface implementation for version OE19 of NDCS in AirFrame.
    """

    def __init__(self, address, port, username, password):
        """
        Redfish interface constructor, initializes protocol, and subsystems offered on this interface.

        :param str address:  Ip address of redfish API
        :param int port: Port of redfish API
        :param str username: Username to login redfish API
        :param str password: Password to login redfish API
        """
        base_url = "{http_protocol}://{address}:{port}".format(
            http_protocol=RedfishConfiguration.default_http_protocol,
            address=address,
            port=port
        )
        self.protocol = redfish_client(
            base_url=base_url,
            username=username,
            password=password
        )

        self.system = SystemOe19(protocol=self.protocol)

    def login(self):
        """
        Login to Redfish RM17 interface using basic authentication
        """
        self.protocol.login()
